// effect only fires once per export submission even if the component re-renders.
useEffect(() => {
  if (
    fetcher.state === "idle" &&
    fetcher.data &&
    "action" in fetcher.data &&
    fetcher.data.action === "export" &&
    "csv" in fetcher.data &&
    !exportTriggeredRef.current
  ) {
    exportTriggeredRef.current = true;
    const csv = fetcher.data.csv as string;
    const blob = new Blob([csv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "zip-codes.csv";
    a.click();
    URL.revokeObjectURL(url);
  }
  if (fetcher.state === "submitting") {
    exportTriggeredRef.current = false;
  }
}, [fetcher.state, fetcher.data]);

